Consider neural networks ${\mathcal{N}}_{\bm{w}}$ belonging to a class of depth-2 neural networks. For the PINN empirical risk corresponding to the $(d+1)$-dimensional Navier–Stokes equations, denoted by $\hat{R}({\mathcal{N}}_{\bm{w}}, {\mathcal{S}}_n)$, where ${\mathcal{S}}_n$ represents the training set, and the corresponding population risk $R({\mathcal{N}}_{\bm{w}})$, the data-averaged worst case generalization error --- defined as the difference between the empirical and population risks --- can be bounded as,
    \begin{align}
        &\mathbb{E}_{{\mathcal{S}}_n} \left[\sup_{{\mathcal{N}}_{\bm{w}}} \left( \hat{R}({\mathcal{N}}_{\bm{w}}, {\mathcal{S}}_n) - R({\mathcal{N}}_{\bm{w}}) \right)\right] \leq \frac{C_r}{\sqrt{N_r}} + \frac{C_0}{\sqrt{N_0}},
    \end{align}
    where $N_r$ denotes the number of training data points in the domain and $N_0$ the number of boundary points corresponding to the initial condition. The constants $C_r$ and $C_0$ can be expressed explicitly in terms of the Lipschitz constant of the loss function, the bounds on certain norms of the weights, the viscosity coefficient, the regularization on the loss terms enforcing the initial-condition and the incompressibility condition, and the bounds on the moments of the data distribution. The constant $C_r$ grows linearly with the viscosity coefficient.

\label{def:huber}
    For some $\delta \geq 0$ the Huber loss is defined as
    \begin{align*}
        \ell_{H,\delta} (x) \coloneqq
        \begin{cases}
            \frac{1}{2} x^2 &\quad \mbox{for } \abs{x}\leq \delta \\
            \delta \cdot (\abs{x} - \frac{1}{2} \delta) &\quad \mbox{for } \abs{x} > \delta
        \end{cases}        
    \end{align*}

\label{def:nn}
    Let $\sigma : \mathbb R \to \mathbb R$, the input ${\bm{z}}=({\bm{x}},t) \in \mathbb R^{d+1}$, the weights ${\bm{W}} \in \mathbb R^{p \times (d+1)}$, where ${\bm{W}} = [ {\bm{w}}_1, {\bm{w}}_2, \dots, {\bm{w}}_p ]^\top$, ${\bm{w}}_q \in \mathbb R^{d+1}$ for $q\in\{1,\dots p\}$, and the frozen second layer weights ${\bm{A}}_1\in\mathbb R^{d\times p}$ and ${\bm{a}}_2\in\mathbb R^p$. Then we can define a neural network ${\mathcal{N}}_{\bm{w}} : [0,1]^{d+1} \rightarrow \mathbb R^{d+1}$ whose output coordinates are denoted as mapping, 
    \[ ({\bm{x}},t) = {\bm{z}} \mapsto ({\mathcal{N}}_{{\bm{w}},u}({\bm{z}}), {\mathcal{N}}_{{\bm{w}},p}({\bm{z}}) )\]
    \[\text{where,}\] 
    \begin{align*}
        {\mathcal{N}}_{{\bm{w}},u}({\bm{z}}) \coloneqq {\bm{A}}_1\sigma({\bm{W}} {\bm{z}}),  ~{\mathcal{N}}_{{\bm{w}},p}({\bm{z}}) \coloneqq \left\langle{\bm{a}}_2,\sigma({\bm{W}} {\bm{z}})\right\rangle
    \end{align*}
    \[\text{and}  ~\sigma({\bm{W}} {\bm{z}}) = [\sigma({\bm{w}}^\top_1 {\bm{z}}), \sigma({\bm{w}}^\top_2 {\bm{z}}),\dots,\sigma({\bm{w}}^\top_p {\bm{z}})]^\top\].

\label{def:collocation}
Let the sampled collocation points available to solve the PDE be denoted as the following two sets of points,

\begin{align*}
\{ ({\bm{x}}_{ri},t_{ti}) \in [0,1]^d \times [0,1] \mid i=1,\ldots,N_r \}, ~\{ {\bm{x}}_{0j} \in [0,1]^d  \mid j=1,\ldots,N_0 \}
\end{align*}

We also assume that there exists constant such that $\mathbb{E}_{{\bm{z}}_{0j}}[\norm{{\bm{z}}_{0j}}_2^2] \leq C_{{\bm{z}}_0}^2, \forall j \in [N_0]$, where ${\bm{z}}_{0j} \coloneqq ({\bm{x}}_{0j},0)$, and $\mathbb{E}_{{\bm{z}}_i}[\norm{{\bm{z}}_i}_2^2] \leq C_{{\bm{z}}}^2, \forall i \in [N_r]$, where ${\bm{z}}_i = ({\bm{x}}_{ri}, t_{ri})$.

\label{def:erisk}
For a Lipschitz loss function $\ell : \mathbb R \rightarrow [0,\infty)$, a neural net ${\mathcal{N}}_{\bm{w}} : [0,1]^{d+1} \rightarrow \mathbb R^{d+1}$ and regularization parameters $\lambda_0, \lambda_1 >0$, the corresponding empirical risk with collocation points given by Definition \ref{def:collocation} can be written as,

\begin{align}
     \hat{R}({\mathcal{N}}_{\bm{w}}) \coloneqq &\frac{1}{N_r}\sum_{i=1}^{N_r} \sum_{k=1}^d\ell \left( (\partial_t {\mathcal{N}}_{{\bm{w}},u})_k + (({\mathcal{N}}_{{\bm{w}},u} \cdot \nabla) {\mathcal{N}}_{{\bm{w}},u})_k + (\nabla {\mathcal{N}}_{{\bm{w}},p})_k - \nu (\nabla^2 {\mathcal{N}}_{{\bm{w}},u})_k \right )\mid_{({\bm{x}}_{ri},t_{ri})} \nonumber\\
     &+ \frac{\lambda_0}{N_r}\sum_{i=1}^{N_r}\ell \left  ( \nabla\cdot {\mathcal{N}}_{{\bm{w}},u} \right )\mid_{({\bm{x}}_{ri},t_{ri})}   + \frac{\lambda_1}{N_0}\sum_{j=1}^{N_0} \sum_{k=1}^d\ell \left ( ({\mathcal{N}}_{{\bm{w}},u}({\bm{x}},0))_k - ({\bm{f}}_0 ({\bm{x}}))_k \right )\mid_{{\bm{x}}_{0j}}
\end{align}

\label{def:lossclass}
    We can define two separate loss functions, $\ell_{res}$ and $\ell_{0}$ s.t they measure the error at any space-time interior point and a spatial point, respectively, as follows,
    \begin{align*}
        \ell_{res}({\mathcal{N}}_{\bm{w}}, ({\bm{x}}_{ri},t_{ri})) &\coloneqq \sum_{k=1}^d\ell \left( (\partial_t {\mathcal{N}}_{{\bm{w}},u})_k + (({\mathcal{N}}_{{\bm{w}},u} \cdot\nabla){\mathcal{N}}_{{\bm{w}},u})_k + (\nabla {\mathcal{N}}_{{\bm{w}},p})_k - \nu (\nabla^2 {\mathcal{N}}_{{\bm{w}},u})_k \right )\mid_{({\bm{x}}_{ri},t_{ri})} \\
        &\hspace{2.00em}+ \lambda_0 \cdot \ell \left  (\grad \cdot {\mathcal{N}}_{{\bm{w}},u} \right )\mid_{({\bm{x}}_{ri},t_{ri})}\\
        \ell_{0}({\mathcal{N}}_{\bm{w}}, {\bm{x}}_{0j}) &\coloneqq \lambda_1 \sum_{k=1}^d \ell \left ( ({\mathcal{N}}_{{\bm{w}},u}({\bm{x}},0))_k - ({\bm{f}}_0 ({\bm{x}}))_k \right )\mid_{{\bm{x}}_{0j}}
    \end{align*}
    and thus the empirical risk can we written as,
    \begin{align}\label{eq:genpinn}
        \hat{R}({\mathcal{N}}_{\bm{w}}) \coloneqq &\frac{1}{N_r}\sum_{i=1}^{N_r} \ell_{res}({\mathcal{N}}_{\bm{w}}, ({\bm{x}}_{ri},t_{ri}))  + \frac{1}{N_0}\sum_{j=1}^{N_0} \ell_{0}({\mathcal{N}}_{\bm{w}}, {\bm{x}}_{0j}).
    \end{align}

The constants in Theorem~\ref{thm:NSRad} for specific choices of activation functions are as follows:
    \begin{enumerate}[(i)]
        \item $\sigma = \tanh$:
        \begin{equation} 
            L_\sigma = L_{\sigma'} = 1,\;\;
            L_\sigma'' = 2,\;\;
            B_\sigma = B_{\sigma'} = 1,\;\;
            c_0 = c_2 = 0,\;\;
            c_1 = 1.
        \end{equation}
        \item $\sigma = \tanh^3$:
        \begin{equation}
            L_\sigma = 0.75,\;\;
            L_{\sigma'} = 1.4,\;\;
            L_\sigma'' = 6,\;\;
            B_\sigma = 1,\;\;
            B_{\sigma'} = 0.75,\;\;
            c_0 = c_1 = c_2 = 0.
        \end{equation}
    \end{enumerate}

\label{lem:NSRad}
    Continuing within the framework of Theorem~\ref{thm:NSRad}, it follows that a way to ensure that the RHS is ${\mathcal{O}}(\epsilon)$ the number of collocation points $N_r$ and initial condition points $N_0$ can be chosen as,
    \begin{align*}
        N_r &= {\mathcal{O}}\left(\frac{\delta^2 (B_{\bm{w}} C_{\bm{z}} C_1 + C_2)^2}{\epsilon^2}\right)\\
        N_0 &= {\mathcal{O}}\left(\frac{\lambda_1^2 \delta^2 B_{\bm{a}}^2 (B_{\bm{w}} C_{{\bm{z}}_0} L_\sigma + \abs{c_0})^2}{\epsilon^2}\right),
    \end{align*}
    where $C_1 \coloneqq 2B_{f_1}L_{\sigma'}+4B_{f_2}(B_\sigma L_{\sigma'}+B_{\sigma'}L_\sigma)+2B_{f_3}L_{\sigma'}+2\nu B_{f_4} L_{\sigma''}+2 \lambda_0 B_{f_5}L_{\sigma'}$ and $C_2 \coloneqq  B_{f_1}\abs{c_1} + B_{f_2}(2B_{\sigma'}\abs{c_0} + \abs{c_0 c_1}) + B_{f_3}\abs{c_1} + \nu B_{f_4}\abs{c_2} + \lambda_0 B_{f_5}\abs{c_1}$.

\label{lem:genbound}
    Continuing in the setup of Definition \ref{def:lossclass}, it follows that,
    \begin{align*}
        &\mathbb{E}_{\substack{({\bm{x}}_{ri},t_{ri}) \sim {\mathcal{D}}_1 \forall i \in [N_r] \\ {\bm{x}}_{0j} \sim {\mathcal{D}}_2 \forall j\in[N_0]}} \Bigg[\sup_{h\in{\mathcal{H}}} \Bigg( \frac{1}{N_r} \sum_{i=i}^{N_r} \ell_{res}(h,({\bm{x}}_{ri},t_{ri})) + \frac{1}{N_0} \sum_{j=i}^{N_0} \ell_{0}(h,{\bm{x}}_{0j}) \\
        &\hspace{15.00em}- \left( \mathbb{E}_{({\bm{x}}_r,t_r) \sim {\mathcal{D}}_1}[\ell_{res}(h,({\bm{x}}_{r},t_{r}))] + \mathbb{E}_{{\bm{x}}_0 \sim {\mathcal{D}}_2}[\ell_{0}(h,{\bm{x}}_{0})] \right) \Bigg)\Bigg]\\
        &\leq 2{\mathcal{R}}_{res} ({\mathcal{H}}) + 2{\mathcal{R}}_{0} ({\mathcal{H}})
    \end{align*}

    where,
    \begin{align*}
        {\mathcal{R}}_{res} ({\mathcal{H}}) &\coloneqq \mathbb{E}_{\substack{({\bm{x}}_{ri},t_{ri}) \sim D_1 \forall i \in [N_r]}}\left[ \mathbb{E}_{\epsilon_i\sim \{\pm 1\}} \left[ \sup_{h\in{\mathcal{H}}} \left(\frac{1}{N_r} \sum_{i=i}^{N_r} \epsilon_i\ell_{res}(h,({\bm{x}}_{ri},t_{ri})) \right) \right] \right] \\
        {\mathcal{R}}_0 ({\mathcal{H}}) &\coloneqq \mathbb{E}_{\substack{{\bm{x}}_{0j}' \sim {\mathcal{D}}_2 \forall j\in[N_0]}} \left[\mathbb{E}_{{\bm{\epsilon}} \sim \{\pm 1\}^{N_0}} \left[ \sup_{h\in{\mathcal{H}}} \left( \frac{1}{N_0} \sum_{j=i}^{N_0} \epsilon_j \ell_{0}(h,{\bm{x}}_{0j}) \right)\right]\right]
    \end{align*}

\label{lem:partialderivatives}
    The specific partial derivatives needed to expand the loss are given by:
    \begin{align*}
        \partial_{x_k} {\mathcal{N}}_{{\bm{w}},p}({\bm{z}}) =\left\langle{\bm{a}}_2\odot{\bm{w}}_{x_k},\sigma'({\bm{W}}{\bm{z}})\right\rangle, ~&(\partial_t{\mathcal{N}}_{{\bm{w}},{\bm{u}}}({\bm{z}}))_k =\left\langle{\bm{a}}_{1k}\odot{\bm{w}}_t,\sigma'({\bm{W}}{\bm{z}})\right\rangle\\
        \nabla\cdot{\mathcal{N}}_{{\bm{w}},u}({\bm{z}})=\sum_{m=1}^d\left\langle{\bm{a}}_{1m}\odot{\bm{w}}_{x_m},\sigma'({\bm{W}}{\bm{z}})\right\rangle,&(({\mathcal{N}}_{{\bm{w}},{\bm{u}}}\cdot\nabla){\mathcal{N}}_{{\bm{w}},{\bm{u}}})_k =\sum_{m=1}^d(\left\langle{\bm{a}}_{1m},\sigma({\bm{W}}{\bm{z}})\right\rangle)(\left\langle{\bm{a}}_{1k}\odot{\bm{w}}_{{\bm{x}}_m},\sigma'({\bm{W}}{\bm{z}})\right\rangle)\\
        (\nabla^2{\mathcal{N}}_{{\bm{w}},{\bm{u}}}({\bm{z}}))_k&=\sum_{m=1}^d\left\langle{\bm{a}}_{1k}\odot{\bm{w}}_{x_m}\odot{\bm{w}}_{x_m},\sigma''({\bm{W}}{\bm{z}})\right\rangle
    \end{align*}
    where ${\bm{z}} = ({\bm{x}}, t)$.

\label{lem:dabsvalremtanh}(A Variation of Lemma 5.12 of \cite{tengyucs229m})
    Given a real valued function $f_{\bm{w}}$ parameterized by ${\bm{w}}$ and a data-set ${\bm{Z}} = ({\bm{z}}_1,\ldots,{\bm{z}}_n)$ define, $f_{\bm{w}}({\bm{Z}}) = (f_{\bm{w}}({\bm{z}}_1),\dots ,f_{\bm{w}}({\bm{z}}_n))$ and $g_{\bm{w}}({\bm{Z}}) = (f_{\bm{w}}({\bm{z}}_1)-c,\dots ,f_{\bm{w}}({\bm{z}}_n)-c)$, where $c \in \mathbb R$ is some constant. Suppose that for any ${\bm{\epsilon}} \in \{\pm 1\}^n$, $\sup_{\bm{w}} \left\langle{\bm{\epsilon}},g_{\bm{w}}({\bm{Z}})\right\rangle \geq 0$. Then,
    \begin{align}
        \mathbb{E}_{{\bm{\epsilon}}\sim\{\pm 1\}^n}\left[ \sup_{\bm{w}} \abs{\left\langle{\bm{\epsilon}},f_{\bm{w}}({\bm{Z}})\right\rangle} \right] \leq 2 \mathbb{E}_{{\bm{\epsilon}}\sim\{\pm 1\}^n}\left[ \sup_{\bm{w}} \left\langle{\bm{\epsilon}},g_{\bm{w}}({\bm{Z}})\right\rangle \right] + \abs{c}\sqrt{n}
    \end{align}

\label{lem:dcontract1tanh}
    Assume that $\phi : \mathbb R \rightarrow \mathbb R$ is an $L_\phi$-Lipschitz continuous, $\phi(0) = c$, for some constant $c \in \mathbb R$, and $\sum_{m=1}^{p} \abs{f({\bm{W}})_m} \leq B$, where $f({\bm{W}}) : \mathbb R^{p \times d} \to \mathbb R^p$. Then,
    \begin{align*}
        \mathbb{E}_{{\bm{\epsilon}} \sim \{\pm 1\}^{N_r}} \left[ \sup_{{\bm{W}}\in{\mathcal{C}}} \left( \frac{1}{N_r} \sum_{i=1}^{N_r} \epsilon_i \left\langlef({\bm{W}}),\phi({\bm{W}} {\bm{z}}_i)\right\rangle \right) \right] \leq \frac{2B L_{\phi}}{N_r} \mathbb{E}_{{\bm{\epsilon}} \sim \{\pm 1\}^{N_r}} \left[ \sup_{\bar{{\bm{w}}}\in\textrm{RS}({\mathcal{C}})} \sum_{i=1}^{N_r} \epsilon_i \left\langle\bar{{\bm{w}}},{\bm{z}}_i\right\rangle \right] + \frac{B\abs{c}}{\sqrt{N_r}}
    \end{align*}

\footnote{The LLM Claude was used in some parts of the proof of Lemma~\ref{lem:dcontract2}}\label{lem:dcontract2}
    Assume that $\phi_1 : \mathbb R \rightarrow \mathbb R$ and $\phi_2 : \mathbb R \to \mathbb R$ are Lipschitz continuous function with Lipschitz constants $L_{\phi_1}$ and $L_{\phi_2}$ respectively, and $\phi_1(0) \cdot \phi_2(0) = k$, for some constant $k \in \mathbb R$. Let $\phi_1 \leq B_{\phi_1}$, $\phi_2 \leq B_{\phi_2}$ and let there be $d$ functions $f_{m},m\in[d]$,$f_m({\bm{W}}) : \mathbb R^{p \times d} \to \mathbb R^p$ such that $\sum_{m=1}^d \sum_{q_1,q_2 = 1}^p \abs{f_m({\bm{W}})_{q_1}} \abs{{\bm{a}}_{m,q_2}} \leq B$. Then, 
    \begin{align}
        &\mathbb{E}_{\substack{{\bm{\epsilon}} \sim \{\pm 1\}^{N_r}}} \left[ \sup_{{\bm{W}}\in{\mathcal{C}}} \left(\frac{1}{N_r} \sum_{i=1}^{N_r} \sum_{m=1}^d\epsilon_i \left\langlef_m({\bm{W}}),\phi_1 ({\bm{W}} {\bm{z}}_i)\right\rangle \left\langle{\bm{a}}_m,\phi_2({\bm{W}} {\bm{z}}_i)\right\rangle \right)\right] \nonumber\\

        &\leq \frac{4B(B_{\phi_1} L_{\phi_2} + B_{\phi_2} L_{\phi_1})}{N_r}\, \mathbb{E}_{\epsilon}\left[\sup_{\bar{{\bm{w}}} \in \mathrm{RS}(C)} \sum_{i=1}^{N_r} \epsilon_i \langle \bar{{\bm{w}}}, {\bm{z}}_i\rangle\right] + \frac{B(2B_{\phi_2}|\phi_1(0)| + |k|)}{\sqrt{N_r}}.
    \end{align}

First we can bound the generalization error by the Rademacher expression of the empirical loss as given by Lemma \ref{lem:genbound}, giving us
    \begin{align*}
       &\mathbb{E}_{\substack{({\bm{x}}_{ri},t_{ri}) \sim {\mathcal{D}}_1 \forall i \in [N_r] \\ {\bm{x}}_{0j} \sim {\mathcal{D}}_2 \forall j\in[N_0]}} \Bigg[\sup_{h\in{\mathcal{H}}} \Bigg( \frac{1}{N_r} \sum_{i=i}^{N_r} \ell_{res}(h,({\bm{x}}_{ri},t_{ri})) + \frac{1}{N_0} \sum_{j=i}^{N_0} \ell_{0}(h,{\bm{x}}_{0j}) \\
        &\hspace{14.00em}- \left( \mathbb{E}_{({\bm{x}}_r,t_r) \sim {\mathcal{D}}_1}[\ell_{res}(h,({\bm{x}}_{r},t_{r}))] + \mathbb{E}_{{\bm{x}}_0 \sim {\mathcal{D}}_2}[\ell_{0}(h,{\bm{x}}_{0})] \right) \Bigg)\Bigg]\\
        &\leq 2{\mathcal{R}}_{res} ({\mathcal{H}}) + 2{\mathcal{R}}_{0} ({\mathcal{H}})
    \end{align*}

    where,
    \begin{align*}
        {\mathcal{R}}_{res} ({\mathcal{H}}) &\coloneqq \mathbb{E}_{\substack{({\bm{x}}_{ri},t_{ri}) \sim D_1 \forall i \in [N_r]}}\left[ \mathbb{E}_{\epsilon_i\sim \{\pm 1\}} \left[ \sup_{h\in{\mathcal{H}}} \left(\frac{1}{N_r} \sum_{i=i}^{N_r} \epsilon_i\ell_{res}(h,({\bm{x}}_{ri},t_{ri})) \right) \right] \right] \\
        {\mathcal{R}}_0 ({\mathcal{H}}) &\coloneqq \mathbb{E}_{\substack{{\bm{x}}_{0j}' \sim {\mathcal{D}}_2 \forall j\in[N_0]}} \left[\mathbb{E}_{{\bm{\epsilon}} \sim \{\pm 1\}^{N_0}} \left[ \sup_{h\in{\mathcal{H}}} \left( \frac{1}{N_0} \sum_{j=i}^{N_0} \epsilon_j \ell_{0}(h,{\bm{x}}_{0j}) \right)\right]\right]
    \end{align*}

    By Definition \ref{def:lossclass}, we substitute the definition of $\ell_{res}$ and $\ell_0$ and the partial derivatives given by Lemma \ref{lem:partialderivatives} to get,
    \begin{align*}
        {\mathcal{R}}_{res} &= \mathbb{E}_{\substack{({\bm{z}}_i\sim D_1)\\\forall i\in[N_r]}}\Biggl[\mathbb{E}_{{\bm{\epsilon}}\sim\{\pm1\}^{N_r}}\Biggl[\sup_{{\bm{W}}\in{\mathcal{C}}}\biggl(\frac{1}{N_r}\sum_{i=1}^{N_r}\epsilon_i\Bigl\{\sum_{k=1}^d\ell\Bigl(\left\langle{\bm{a}}_{1k}\odot{\bm{w}}_{t},\sigma'({\bm{W}}{\bm{z}})\right\rangle +\sum_{m=1}^d(\left\langle{\bm{a}}_{1m},\sigma({\bm{W}}{\bm{z}}_i)\right\rangle)(\left\langle{\bm{a}}_{1k}\odot{\bm{w}}_{{\bm{x}}_m},\sigma'({\bm{W}}{\bm{z}}_i)\right\rangle) \nonumber\\
        &\hspace{7.00em}+ \left\langle{\bm{a}}_{2}\odot{\bm{w}}_{x_k},\sigma'({\bm{W}}{\bm{z}}_i)\right\rangle-\nu\sum_{m=1}^d\left\langle{\bm{a}}_{1k}\odot{\bm{w}}_{x_m}\odot{\bm{w}}_{x_m},\sigma''({\bm{W}}{\bm{z}}_i)\right\rangle\Bigr) + \lambda_0\ell\Bigl(\sum_{m=1}^d\left\langle{\bm{a}}_{1m}\odot{\bm{w}}_{x_m},\sigma'({\bm{W}}{\bm{z}}_i)\right\rangle\Bigr)\Bigr\}\biggr)\Biggr]\Biggr],
    \end{align*}
    where ${\bm{z}}_i = ({\bm{x}}_{ri}, t_{ri})$.
    \begin{align*}
        {\mathcal{R}}_0 = \lambda_1 \mathbb{E}_{\substack{{\bm{x}}_{0j}' \sim {\mathcal{D}}_2 \forall j\in[N_0]}} \left[\mathbb{E}_{{\bm{\epsilon}} \sim \{\pm 1\}^{N_0}} \left[ \sup_{{\bm{W}}\in{\mathcal{C}}} \left( \frac{1}{N_0} \sum_{j=i}^{N_0} \sum_{k=1}^d\epsilon_j \ell \left ( ({\mathcal{N}}_{{\bm{w}},u}({\bm{x}}_{0j},0))_k - ({\bm{f}}_0 ({\bm{x}}_{0j}))_k \right ) \right)\right] \right],
    \end{align*}

    Firstly we focus on ${\mathcal{R}}_{res}$ and we rewrite as the following sum splitting across the regularization for the divergenceless condition.

    \begin{align*}
        {\mathcal{R}}_{res} &= \mathbb{E}_{\substack{({\bm{z}}_i\sim D_1)\\\forall i\in[N_r]}}\Biggl[\mathbb{E}_{{\bm{\epsilon}}\sim\{\pm1\}^{N_r}}\Biggl[\sup_{{\bm{W}}\in{\mathcal{C}}}\biggl(\frac{1}{N_r}\sum_{i=1}^{N_r}\epsilon_i\Bigl\{\sum_{k=1}^d\ell\Bigl(\left\langle{\bm{a}}_{1k}\odot{\bm{w}}_{t},\sigma'({\bm{W}}{\bm{z}})\right\rangle +\sum_{m=1}^d(\left\langle{\bm{a}}_{1m},\sigma({\bm{W}}{\bm{z}}_i)\right\rangle)(\left\langle{\bm{a}}_{1k}\odot{\bm{w}}_{{\bm{x}}_m},\sigma'({\bm{W}}{\bm{z}}_i)\right\rangle) \nonumber\\
        &\hspace{7.00em}+ \left\langle{\bm{a}}_{2}\odot{\bm{w}}_{x_k},\sigma'({\bm{W}}{\bm{z}}_i)\right\rangle-\nu\sum_{m=1}^d\left\langle{\bm{a}}_{1k}\odot{\bm{w}}_{x_m}\odot{\bm{w}}_{x_m},\sigma''({\bm{W}}{\bm{z}}_i)\right\rangle\Bigr)\Bigr\}\biggr)\Biggr]\Biggr] \\
        &\hspace{2.00em} + \mathbb{E}_{\substack{({\bm{z}}_i\sim D_1)\\\forall i\in[N_r]}}\Biggl[\mathbb{E}_{{\bm{\epsilon}}\sim\{\pm1\}^{N_r}}\Biggl[\sup_{{\bm{W}}\in{\mathcal{C}}}\biggl(\frac{1}{N_r}\sum_{i=1}^{N_r}\epsilon_i\Bigl\{\lambda_0\ell\Bigl(\sum_{m=1}^d\left\langle{\bm{a}}_{1m}\odot{\bm{w}}_{x_m},\sigma'({\bm{W}}{\bm{z}}_i)\right\rangle\Bigr)\Bigr\}\biggr)\Biggr]\Biggr]
    \end{align*}
    Using the assumption from Definition \ref{def:nn} that the loss is $L_\ell$-Lipschitz, we can use Talagrand's contraction lemma on each of the terms separately to get,
    \begin{align}\label{eq:Rres}
        {\mathcal{R}}_{res}&\leq L_\ell \mathbb{E}_{\substack{({\bm{z}}_i\sim D_1)\\\forall i\in[N_r]}}\Biggl[\mathbb{E}_{{\bm{\epsilon}}\sim\{\pm1\}^{N_r}}\Biggl[\sup_{{\bm{W}}\in{\mathcal{C}}}\biggl(\frac{1}{N_r}\sum_{i=1}^{N_r}\epsilon_i\Bigl\{\sum_{k=1}^d\Bigl(\left\langle{\bm{a}}_{1k}\odot{\bm{w}}_{t},\sigma'({\bm{W}}{\bm{z}}_i)\right\rangle \nonumber\\
        &\hspace{14.00em}+\sum_{m=1}^d(\left\langle{\bm{a}}_{1m},\sigma({\bm{W}}{\bm{z}}_i)\right\rangle)(\left\langle{\bm{a}}_{1k}\odot{\bm{w}}_{{\bm{x}}_m},\sigma'({\bm{W}}{\bm{z}}_i)\right\rangle)\nonumber\\
        &\hspace{14.00em}+\left\langle{\bm{a}}_{2}\odot{\bm{w}}_{x_k},\sigma'({\bm{W}}{\bm{z}}_i)\right\rangle-\nu\sum_{m=1}^d\left\langle{\bm{a}}_{1k}\odot{\bm{w}}_{x_m}\odot{\bm{w}}_{x_m},\sigma''({\bm{W}}{\bm{z}}_i)\right\rangle\Bigr)\Bigr\}\biggr)\Biggr]\Biggr]\nonumber\\
        &+ L_\ell \mathbb{E}_{\substack{({\bm{z}}_i\sim D_1)\\\forall i\in[N_r]}}\Biggl[\mathbb{E}_{{\bm{\epsilon}}\sim\{\pm1\}^{N_r}}\Biggl[\sup_{{\bm{W}}\in{\mathcal{C}}}\biggl(\frac{1}{N_r}\sum_{i=1}^{N_r}\epsilon_i\Bigl\{\lambda_0\sum_{m=1}^d\left\langle{\bm{a}}_{1m}\odot{\bm{w}}_{x_m},\sigma'({\bm{W}}{\bm{z}}_i)\right\rangle\Bigr\}\biggr)\Biggr]\Biggr]
    \end{align}



 Observing the structure of the above we define the following five quantities.


