    {\@ssect{\z@}{-12pt \@plus -4pt \@minus -2pt}{6pt}{\reset@font\fontfamily{\rmdefault}\fontsize{12bp}{14bp}\bfseries\selectfont\rightskip0pt plus 1fil\parfillskip=0pt\relax\boldmath}} 
    {\@dblarg{\@sect{subsection}{2}{\z@}{-12pt \@plus -4pt \@minus -2pt}{6pt}{\reset@font\fontfamily{\rmdefault}\fontsize{12bp}{14bp}\bfseries\selectfont\rightskip0pt plus 1fil\parfillskip=0pt\relax\boldmath}}}*{Divide and Conquer}
    Let  ${\mathcal{R}}_1,{\mathcal{R}}_2,{\mathcal{R}}_3,{\mathcal{R}}_4,{\mathcal{R}}_5$ be such that
    \begin{align*}
        {\mathcal{R}}_1&=\mathbb{E}_{{\bm{\epsilon}}\sim\{\pm1\}^{N_r}}\Biggl[\sup_{{\bm{W}}\in{\mathcal{C}}}\biggl(\frac{1}{N_r}\sum_{i=1}^{N_r}\epsilon_i\left\langle{\bm{a}}_{1}\odot{\bm{w}}_{t},\sigma'({\bm{W}}{\bm{z}}_i)\right\rangle\biggr)\Biggr]=\mathbb{E}_{{\bm{\epsilon}}\sim\{\pm1\}^{N_r}}\Biggl[\sup_{{\bm{W}}\in{\mathcal{C}}}\biggl(\frac{1}{N_r}\sum_{i=1}^{N_r}\epsilon_i\left\langlef_1({\bm{W}}),\sigma'({\bm{W}}{\bm{z}}_i)\right\rangle\biggr)\Biggr]\\
        {\mathcal{R}}_2&=\mathbb{E}_{{\bm{\epsilon}}\sim\{\pm1\}^{N_r}}\Biggl[\sup_{{\bm{W}}\in{\mathcal{C}}}\biggl(\frac{1}{N_r}\sum_{i=1}^{N_r}\sum_{k=1}^d\sum_{m=1}^d\epsilon_i\left\langle{\bm{a}}_{1m},\sigma({\bm{W}}{\bm{z}}_i)\right\rangle\left\langle{\bm{a}}_{1k}\odot{\bm{w}}_{{\bm{x}}_m},\sigma'({\bm{W}}{\bm{z}}_i)\right\rangle\biggr)\Biggr]\\
        &=\mathbb{E}_{{\bm{\epsilon}}\sim\{\pm1\}^{N_r}}\Biggl[\sup_{{\bm{W}}\in{\mathcal{C}}}\biggl(\frac{1}{N_r}\sum_{i=1}^{N_r}\sum_{m=1}^d\epsilon_i\left\langlef_{2m}({\bm{W}}),\sigma'({\bm{W}}{\bm{z}}_i)\right\rangle\left\langle{\bm{a}}_{1m},\sigma({\bm{W}}{\bm{z}}_i)\right\rangle\biggr)\Biggr]&\\
        {\mathcal{R}}_3&=\mathbb{E}_{{\bm{\epsilon}}\sim\{\pm1\}^{N_r}}\Biggl[\sup_{{\bm{W}}\in{\mathcal{C}}}\biggl(\frac{1}{N_r}\sum_{i=1}^{N_r}\epsilon_i\left\langle{\bm{a}}_{2}\odot{\bm{w}}_{\bm{x}},\sigma'({\bm{W}}{\bm{z}}_i)\right\rangle\biggr)\Biggr]=\mathbb{E}_{{\bm{\epsilon}}\sim\{\pm1\}^{N_r}}\Biggl[\sup_{{\bm{W}}\in{\mathcal{C}}}\biggl(\frac{1}{N_r}\sum_{i=1}^{N_r}\epsilon_i\left\langlef_3({\bm{W}}),\sigma'({\bm{W}}{\bm{z}}_i)\right\rangle\biggr)\Biggr]\\
        {\mathcal{R}}_4
        &=\mathbb{E}_{{\bm{\epsilon}}\sim\{\pm1\}^{N_r}}\Biggl[\sup_{{\bm{W}}\in{\mathcal{C}}}\biggl(\frac{-\nu}{N_r}\sum_{i=1}^{N_r}\sum_{m=1}^d\epsilon_i\left\langle{\bm{a}}_{1}\odot{\bm{w}}_{x_m}\odot{\bm{w}}_{x_m},\sigma''({\bm{W}}{\bm{z}}_i)\right\rangle\biggr)\Biggr]=\mathbb{E}_{{\bm{\epsilon}}\sim\{\pm1\}^{N_r}}\Biggl[\sup_{{\bm{W}}\in{\mathcal{C}}}\biggl(\frac{-\nu}{N_r}\sum_{i=1}^{N_r}\epsilon_i\left\langlef_4({\bm{W}}),\sigma''({\bm{W}}{\bm{z}}_i)\right\rangle\biggr)\Biggr]\\
        {\mathcal{R}}_5
        &=\mathbb{E}_{{\bm{\epsilon}}\sim\{\pm1\}^{N_r}}\Biggl[\sup_{{\bm{W}}\in{\mathcal{C}}}\biggl(\frac{\lambda_0}{N_r}\sum_{i=1}^{N_r}\sum_{m=1}^d\epsilon_i\left\langle{\bm{a}}_{1m}\odot{\bm{w}}_{x_m},\sigma'({\bm{W}}{\bm{z}}_i)\right\rangle\biggr)\Biggr]=\mathbb{E}_{{\bm{\epsilon}}\sim\{\pm1\}^{N_r}}\Biggl[\sup_{{\bm{W}}\in{\mathcal{C}}}\biggl(\frac{\lambda_0}{N_r}\sum_{i=1}^{N_r}\epsilon_i\left\langlef_5({\bm{W}}),\sigma'({\bm{W}}{\bm{z}}_i)\right\rangle\biggr)\Biggr]
    \end{align*}     

Hence we can rewrite equation \ref{eq:Rres} to get,

    \begin{align*} 
        {\mathcal{R}}_{res}&\leq L_\ell\mathbb{E}_{\substack{({\bm{x}}_{ri},t_{ri}\sim D_1)\\\forall i\in[N_r]}}\Biggl[{\mathcal{R}}_1+{\mathcal{R}}_2+{\mathcal{R}}_3+{\mathcal{R}}_4+{\mathcal{R}}_5\Biggr]&
    \end{align*}




    \textbf{Bounding Terms 1, 3 and 5}


    We recall the Lipschitz constants $L_{\sigma'}$ for $\sigma'(\cdot)$ and $\sigma'(0) = c_1$. Therefore, for ${\mathcal{R}}_1, {\mathcal{R}}_3$, and ${\mathcal{R}}_5$, we can invoke Lemma \ref{lem:dcontract1tanh}, with $\phi(\cdot) = \sigma'(\cdot)$, and recalling the definition of $B_{f_1}, B_{f_3}$ and $B_{f_5}$ from Definition~\ref{def:Wspace} to get
    \begin{align*}
        {\mathcal{R}}_{1} &\leq \frac{2 B_{f_1} L_{\sigma'}}{N_r} \mathbb{E}_{\substack{{\bm{\epsilon}} \sim \{\pm 1\}^{N_r}}} \left[ \sup_{\bar{{\bm{w}}}\in\textrm{RS}({\mathcal{C}})} \sum_{i=1}^{N_r} \epsilon_i \left\langle\bar{{\bm{w}}},{\bm{z}}_i\right\rangle \right ] + \frac{B_{f_1} \abs{c_1}}{\sqrt{N_r}} \\
        {\mathcal{R}}_{3} &\leq \frac{2 B_{f_3} L_{\sigma'}}{N_r} \mathbb{E}_{\substack{{\bm{\epsilon}} \sim \{\pm 1\}^{N_r}}} \left[ \sup_{\bar{{\bm{w}}}\in\textrm{RS}({\mathcal{C}})} \sum_{i=1}^{N_r} \epsilon_i \left\langle\bar{{\bm{w}}},{\bm{z}}_i\right\rangle \right ] + \frac{B_{f_3} \abs{c_1}}{\sqrt{N_r}}\\
        {\mathcal{R}}_{5} &\leq \frac{2 \lambda_0 B_{f_5} L_{\sigma'}}{N_r} \mathbb{E}_{\substack{{\bm{\epsilon}} \sim \{\pm 1\}^{N_r}}} \left[ \sup_{\bar{{\bm{w}}}\in\textrm{RS}({\mathcal{C}})} \sum_{i=1}^{N_r} \epsilon_i \left\langle\bar{{\bm{w}}},{\bm{z}}_i\right\rangle \right] + \frac{B_{f_5} \abs{c_1}}{\sqrt{N_r}}
    \end{align*}



    \textbf{Bounding Term 2}

    Since $\sigma(\cdot)$ is $L_{\sigma}$-Lipschitz, $\sigma(\cdot) \leq B_{\sigma}$, $\sigma'(\cdot)$ is $L_{\sigma'}$-Lipschitz, $\sigma'(\cdot) \leq B_{\sigma'}$, and $\sigma(0) \cdot \sigma'(0) = c_0 c_1$ , we can apply Lemma \ref{lem:dcontract2} with, $\phi_1(\cdot) = \sigma(\cdot)$, $\phi_2(\cdot) = \sigma'(\cdot)$ and $k = c_0 c_1$ , and recalling the definition of $B_{f_2}$ from Definition~\ref{def:Wspace} to get




    \begin{align*}
        {\mathcal{R}}_2 \leq \frac{4B_{f_2}(B_{\sigma} L_{\sigma'} + B_{\sigma'} L_{\sigma})}{N_r}\, \mathbb{E}_{\epsilon}\left[\sup_{\bar{w} \in RS(C)} \sum_{i=1}^{N_r} \epsilon_i \langle \bar{{\bm{w}}}, {\bm{z}}_i\rangle\right] + \frac{B_{f_2}(2B_{\sigma'}|c_0| + |c_0 c_1|)}{\sqrt{N_r}}
    \end{align*}




    \textbf{Bounding Term 4}

    For the 4th term, since we are taking the expectation for $\epsilon_i \sim \{\pm 1\}$, we can simplify ${\mathcal{R}}_4$ as
    \begin{align*}
        {\mathcal{R}}_4 =\mathbb{E}_{{\bm{\epsilon}}\sim\{\pm1\}^{N_r}}\Biggl[\sup_{{\bm{W}}\in{\mathcal{C}}}\biggl(\frac{\nu}{N_r}\sum_{i=1}^{N_r}\epsilon_i\left\langlef_4({\bm{W}}),\sigma''({\bm{W}}{\bm{z}}_i)\right\rangle\biggr)\Biggr].
    \end{align*}
    We recall the Lipschitz constants $L_{\sigma''}$ for $\sigma''(\cdot)$ and $\sigma''(0) = c_2$. Therefore, for ${\mathcal{R}}_4$, we can invoke Lemma \ref{lem:dcontract1tanh} with $\phi(\cdot) = \sigma''(\cdot)$ and recalling the definition of $B_{f_4}$ from Definition~\ref{def:Wspace} to get 

    \begin{align*}
        {\mathcal{R}}_{4} &\leq \frac{2\nu B_{f_4} L_{\sigma''}}{N_r} \mathbb{E}_{\substack{{\bm{\epsilon}} \sim \{\pm 1\}^{N_r}}} \left[ \sup_{\bar{{\bm{w}}} \in \textrm{RS}({\mathcal{C}})} \sum_{i=1}^{N_r} \epsilon_i \left\langle\bar{{\bm{w}}},{\bm{z}}_i\right\rangle \right ] + \frac{\nu B_{f_4} \abs{c_2}}{\sqrt{N_r}}.
    \end{align*}


