    \begin{align*}
        {\mathcal{R}}_{res} &\leq L_\ell ( {\mathcal{R}}_1 + {\mathcal{R}}_2 + {\mathcal{R}}_3 + {\mathcal{R}}_4 + {\mathcal{R}}_5 )\\


        &\leq L_\ell\left(\frac{2B_{f_1}L_{\sigma'}+4B_{f_2}(B_\sigma L_{\sigma'}+B_{\sigma'}L_\sigma)+2B_{f_3}L_{\sigma'}+2\nu B_{f_4}(L_{\sigma'}+L_{\sigma})+2 \lambda_0 B_{f_5}L_{\sigma'}}{N_r}\right)\times \mathbb{E}_{{\bm{\epsilon}}\sim\{\pm1\}^{N_r}}\left[\sup_{\bar{{\bm{w}}}\in\textrm{RS}({\mathcal{C}})}\sum_{i=1}^{N_r}\epsilon_i\left\langle\bar{{\bm{w}}},{\bm{z}}_i\right\rangle\right] \\
        &\hspace{2.00em}+ \frac{L_\ell (B_{f_1}\abs{c_1} + B_{f_2}(2B_{\sigma'}\abs{c_0} + \abs{c_0 c_1}) + B_{f_3}\abs{c_1} + \nu B_{f_4}c_2 + \lambda_0 B_{f_5}\abs{c_1})}{\sqrt{N_r}}
    \end{align*}







    So, we are finally left with a Rademacher complexity of a linear model
    \begin{align*}
        \hat{{\mathcal{R}}}_{res} \leq \frac{L_\ell C_1}{N_r} \mathbb{E}_{\substack{{\bm{\epsilon}} \sim \{\pm 1\}^{N_r}}} \left[ \sup_{\bar{{\bm{w}}}\in\textrm{RS}({\mathcal{C}})} \sum_{i=1}^{N_r} \epsilon_i \left\langle\bar{{\bm{w}}},{\bm{z}}_i\right\rangle\right] + \frac{L_\ell C_2}{\sqrt{N_r}},
    \end{align*}
    where $C_1 \coloneqq 2B_{f_1}L_{\sigma'}+4B_{f_2}(B_\sigma L_{\sigma'}+B_{\sigma'}L_\sigma)+2B_{f_3}L_{\sigma'}+2\nu B_{f_4}(L_{\sigma'}+L_{\sigma})+2 \lambda_0 B_{f_5}L_{\sigma'}$ and $C_2 \coloneqq  B_{f_1}\abs{c_1} + B_{f_2}(2B_{\sigma'}\abs{c_0} + \abs{c_0 c_1}) + B_{f_3}\abs{c_1} + \nu B_{f_4}\abs{c_2} + \lambda_0 B_{f_5}\abs{c_1}$.

    We recall that $\norm{{\bm{w}}_q}_2 \leq B_{{\bm{w}}}, \forall q \in [p]$, where ${\bm{w}}_q = {\bm{W}}_{q,:}$, and $\mathbb{E}_{{\bm{z}}_i}[\norm{{\bm{z}}_i}_2^2] \leq C_{{\bm{z}}}^2, \forall i \in [N_r]$, where ${\bm{z}}_i = ({\bm{x}}_{ri}, t_{ri})$ from Definition~\ref{def:collocation}. Then using the standard Rademacher complexity bound for linear models (Theorem 5.5 of \cite{tengyucs229m}) we get,
    \begin{align*}
        \hat{{\mathcal{R}}}_{res} \leq \frac{L_\ell B_{{\bm{w}}} C_1}{N_r} \sqrt{\sum_{i=1}^{N_r} \norm{{\bm{z}}_i}_2^2} + \frac{L_\ell C_2}{\sqrt{N_r}}
    \end{align*}
    and taking the expectation over the data gives us,
    \begin{align}
        {\mathcal{R}}_{res} \leq \frac{L_\ell (B_{{\bm{w}}} C_{\bm{z}} C_1 + C_2)}{\sqrt{N_r}}.
    \end{align}





