    {\@dblarg{\@sect{subsection}{2}{\z@}{-12pt \@plus -4pt \@minus -2pt}{6pt}{\reset@font\fontfamily{\rmdefault}\fontsize{12bp}{14bp}\bfseries\selectfont\rightskip0pt plus 1fil\parfillskip=0pt\relax\boldmath}}}*{Analysing the Initial Condition Enforcing Term}

    \begin{align*}
        {\mathcal{R}}_0 = \lambda_1 \mathbb{E}_{{\bm{\epsilon}} \sim \{\pm 1\}^{N_0}} \left[ \sup_{{\bm{W}}\in{\mathcal{C}}} \left( \frac{1}{N_0} \sum_{j=i}^{N_0} \sum_{k=1}^d\epsilon_j \ell \left ( ({\mathcal{N}}_{{\bm{w}},u}({\bm{x}}_{0j},0))_k - ({\bm{f}}_0 ({\bm{x}}_{0j}))_k \right ) \right)\right]
    \end{align*}

    Since the loss $\ell$ is Lipschitz with constant $L_\ell$ we can apply Talagrand's contraction to get
    \begin{align*}
        &\leq \frac{\lambda_1 L_\ell}{N_0} \mathbb{E}_{{\bm{\epsilon}} \sim \{\pm 1\}^{N_0}} \left[ \sup_{{\bm{W}}\in{\mathcal{C}}} \left( \sum_{j=i}^{N_0} \sum_{k=1}^d\epsilon_j (({\mathcal{N}}_{{\bm{w}},u}({\bm{x}}_{0j},0))_k - ({\bm{f}}_0 ({\bm{x}}_{0j}))_k) \right)\right] \\
        &= \frac{\lambda_1 L_\ell}{N_0} \mathbb{E}_{{\bm{\epsilon}} \sim \{\pm 1\}^{N_0}} \left[ \sup_{{\bm{W}}\in{\mathcal{C}}} \left( \sum_{j=i}^{N_0} \sum_{k=1}^d\epsilon_j ({\mathcal{N}}_{{\bm{w}},u}({\bm{x}}_{0j},0))_k \right)\right].
    \end{align*}
    Let's define ${\bm{z}}_{0j} \coloneqq ({\bm{x}}_{0j},0)$, then we can simplify the above as
    \begin{align*}
        &= \frac{\lambda_1 L_\ell}{N_0} \mathbb{E}_{{\bm{\epsilon}} \sim \{\pm 1\}^{N_0}} \left[ \sup_{{\bm{W}}\in{\mathcal{C}}} \left( \sum_{j=i}^{N_0} \epsilon_j \left\langle{\bm{a}}_1,\sigma({\bm{W}}{\bm{z}}_{0j})\right\rangle \right)\right] \\
        &= \frac{\lambda_1 L_\ell}{N_0} \mathbb{E}_{{\bm{\epsilon}} \sim \{\pm 1\}^{N_0}} \left[ \sup_{{\bm{w}}_q \in\textrm{RS}({\mathcal{C}})} \left( \sum_{q=1}^p ({\bm{a}}_1)_q \sum_{j=i}^{N_0} \epsilon_j \sigma(\left\langle{\bm{w}}_q,{\bm{z}}_{0j}\right\rangle)\right)\right]\\
        &\leq \frac{\lambda_1 L_\ell}{N_0} \mathbb{E}_{{\bm{\epsilon}} \sim \{\pm 1\}^{N_0}} \left[ \sup_{{\bm{w}}_r \in\textrm{RS}({\mathcal{C}})} \left( \sum_{q=1}^p \abs{({\bm{a}}_1)_q} \max_{r \in [p]} \abs{\sum_{j=i}^{N_0} \epsilon_j \sigma(\left\langle{\bm{w}}_r,{\bm{z}}_{0j}\right\rangle)} \right)\right]
    \end{align*}
    Using our assumption that $\sum_{q=1}^p \abs{({\bm{a}}_1)_q} \leq B_{\bm{a}}$, we can say that,
    \begin{align*}
        &\leq \frac{\lambda_1 L_\ell B_{\bm{a}}}{N_0} \mathbb{E}_{{\bm{\epsilon}} \sim \{\pm 1\}^{N_0}} \left[ \sup_{{\bm{w}}_r \in\textrm{RS}({\mathcal{C}})} \left( \max_{r \in [p]} \abs{\sum_{j=i}^{N_0} \epsilon_j \sigma(\left\langle{\bm{w}}_{r},{\bm{z}}_{0j}\right\rangle)}\right)\right] \\
        &\leq \frac{\lambda_1 L_\ell B_{\bm{a}}}{N_0} \mathbb{E}_{{\bm{\epsilon}} \sim \{\pm 1\}^{N_0}} \left[ \sup_{{\bm{w}}_r \in\textrm{RS}({\mathcal{C}})} \left( \abs{\sum_{j=i}^{N_0} \epsilon_j \sigma(\left\langle{\bm{w}}_r,{\bm{z}}_{0j}\right\rangle)} \right)\right] 
    \end{align*}

    Utilizing the fact that $\sigma(0) = c_0$ if we set $\chi(\cdot) = \phi(\cdot) - c_0$, we note that for any ${\bm{\epsilon}} \in \{\pm 1\}^{N_r}$, $\sup_{{\bm{w}}} \left\langle{\bm{\epsilon}},\chi({\bm{Z}}^\top{\bm{w}})\right\rangle \geq 0$, where ${\bm{Z}} = [{\bm{z}}_1,\dots,{\bm{z}}_{N_r}]$. Hence, we can apply Lemma~\ref{lem:dabsvalremtanh} to get,
    \begin{align*}
        &\leq \frac{ \lambda_1 L_\ell B_{\bm{a}}}{N_0} \Bigg\{2\mathbb{E}_{{\bm{\epsilon}} \sim \{\pm 1\}^{N_0}} \left[ \sup_{{\bm{w}}_r\in\textrm{RS}({\mathcal{C}})} \left( \sum_{j=i}^{N_0} \epsilon_j \sigma(\left\langle{\bm{w}}_r,{\bm{z}}_{0j}\right\rangle) \right)\right] + \abs{c_0} \sqrt{N_0} \Bigg\}
    \end{align*}
    Now, since $\sigma(\cdot)$ is $L_\sigma$-Lipschitz, we can further apply Talagrand's contraction to get,
    \begin{align*}
        &\leq \frac{2 \lambda_1 L_\ell L_\sigma B_{\bm{a}}}{N_0} \mathbb{E}_{{\bm{\epsilon}} \sim \{\pm 1\}^{N_0}} \left[ \sup_{{\bm{w}}_r\in\textrm{RS}({\mathcal{C}})} \left( \sum_{j=i}^{N_0} \epsilon_j \left\langle{\bm{w}}_r,{\bm{z}}_{0j}\right\rangle \right)\right] + \frac{\lambda_1 L_\ell B_{\bm{a}} \abs{c_0}}{\sqrt{N_0}}\\
    \end{align*}
    We recall that $\norm{{\bm{w}}_r}_2 \leq B_{{\bm{w}}}, \forall r \in [p]$, where ${\bm{w}}_r = {\bm{W}}_{r,:}$, and $\mathbb{E}_{{\bm{z}}_{0j}}[\norm{{\bm{z}}_{0j}}_2^2] \leq C_{{\bm{z}}_0}^2, \forall j \in [N_0]$, from Definition~\ref{def:collocation}. Then using the standard Rademacher complexity bound for linear models (Theorem 5.5 of \cite{tengyucs229m}),
    \begin{align*}
        \hat{{\mathcal{R}}}_{0} \leq \frac{2 \lambda_1 L_\ell B_{{\bm{w}}} L_\sigma B_{\bm{a}}}{N_0}\sqrt{\sum_{j=1}^{N_0} \norm{{\bm{z}}_{0j}}^2} + \frac{\lambda_1 L_\ell B_{\bm{a}} \abs{c_0}}{\sqrt{N_0}}
    \end{align*}
    and taking the expectation over the data gives us,
    \begin{align}
        {\mathcal{R}}_{0} \leq \frac{\lambda_1 L_\ell B_{\bm{a}} (2B_{{\bm{w}}} C_{{\bm{z}}_0} L_\sigma + \abs{c_0})}{\sqrt{N_0}} . \label{eq:radboundini:1}
    \end{align}

    Therefore, combining the above with the bound on ${\mathcal{R}}_{\rm res}$ derived earlier we can bound the empirical Rademacher complexity as,
    \begin{align*}
        &{\mathcal{R}}_{\rm res} +{\mathcal{R}}_0 \leq \frac{L_\ell (B_{{\bm{w}}} C_{\bm{z}} C_1 + C_2)}{\sqrt{N_r}} + \frac{\lambda_1 L_\ell B_{\bm{a}} (2B_{{\bm{w}}} C_{{\bm{z}}_0} L_\sigma + \abs{c_0})}{\sqrt{N_0}}
    \end{align*}


        where $C_1 \coloneqq 2B_{f_1}L_{\sigma'}+4B_{f_2}(B_\sigma L_{\sigma'}+B_{\sigma'}L_\sigma)+2B_{f_3}L_{\sigma'}+2\nu B_{f_4} L_{\sigma''}+2 \lambda_0 B_{f_5}L_{\sigma'}$ and $C_2 \coloneqq  B_{f_1}\abs{c_1} + B_{f_2}(2B_{\sigma'}\abs{c_0} + \abs{c_0 c_1}) + B_{f_3}\abs{c_1} + \nu B_{f_4}\abs{c_2} + \lambda_0 B_{f_5}\abs{c_1}$.




    Further, by setting the loss function $\ell$ to be the Huber loss $\ell_{H,\delta}$ for some $\delta > 0$ as in Definition~\ref{def:huber}, we can simplify the above bound to
    \begin{align}
        &{\mathcal{R}}_{\rm res} +{\mathcal{R}}_0 \leq \frac{\delta (B_{{\bm{w}}} C_{\bm{z}} C_1 + C_2)}{\sqrt{N_r}} + \frac{\lambda_1 \delta B_{\bm{a}} (2 B_{{\bm{w}}} C_{{\bm{z}}_0} L_\sigma + \abs{c_0})}{\sqrt{N_0}}
    \end{align}


    where $C_1 \coloneqq 2B_{f_1}L_{\sigma'}+4B_{f_2}(B_\sigma L_{\sigma'}+B_{\sigma'}L_\sigma)+2B_{f_3}L_{\sigma'}+2\nu B_{f_4} L_{\sigma''}+2 \lambda_0 B_{f_5}L_{\sigma'}$ and $C_2 \coloneqq  B_{f_1}\abs{c_1} + B_{f_2}(2B_{\sigma'}\abs{c_0} + \abs{c_0 c_1}) + B_{f_3}\abs{c_1} + \nu B_{f_4}\abs{c_2} + \lambda_0 B_{f_5}\abs{c_1}$.

The net's full output is given by:
\[({\mathcal{N}}_{{\bm{w}},u}({\bm{z}}))_i=\sum_{j=1}^pa_{1ij}\sigma\left(\sum_{k=1}^dw_{jk}x_k+w_{j,d+1}t\right),\]
where ${\bm{z}} = ({\bm{x}}, t)$. The first order partial derivatives of ${\mathcal{N}}_{{\bm{w}}}$ are 
\begin{align*}
    \partial_{x_k} {\mathcal{N}}_{{\bm{w}},p}({\bm{z}}) &= \sum_{j=1}^p a_{2j} \sigma'\left(\sum_{q=1}^dw_{j,q}x_q+w_{j,d+1}t\right)w_{j,k}=\left\langle{\bm{a}}_2\odot{\bm{w}}_{x_k},\sigma'({\bm{W}}{\bm{z}})\right\rangle\\
    (\partial_t{\mathcal{N}}_{{\bm{w}},{\bm{u}}}({\bm{z}}))_k&=\sum_{j=1}^pa_{1k,j}\sigma'\left(\sum_{q=1}^dw_{j,q}x_q+w_{j,d+1}t\right)w_{j,d+1}=\left\langle{\bm{a}}_{1k}\odot{\bm{w}}_t,\sigma'({\bm{W}}{\bm{z}})\right\rangle\\
    (\partial_{x_m}{\mathcal{N}}_{{\bm{w}},{\bm{u}}}({\bm{z}}))_k&=\sum_{j=1}^pa_{1k,j}\sigma'\left(\sum_{q=1}^dw_{j,q}x_q+w_{j,d+1}t\right)w_{j,m}=\left\langle{\bm{a}}_{1k}\odot{\bm{w}}_{x_m},\sigma'({\bm{W}}{\bm{z}})\right\rangle\\
\end{align*}
Using these we can show the non-linear term can be expressed as
\begin{align*}
    \nabla\cdot{\mathcal{N}}_{{\bm{w}},u}({\bm{z}})&=\sum_{m=1}^d\sum_{j=1}^pa_{1m,j}\sigma'\left(\sum_{q=1}^dw_{j,q}x_q+w_{j,d+1}t\right)w_{j,m}=\sum_{m=1}^d\left\langle{\bm{a}}_{1m}\odot{\bm{w}}_{x_m},\sigma'({\bm{W}}{\bm{z}})\right\rangle\\
    \implies(({\mathcal{N}}_{{\bm{w}},{\bm{u}}}\cdot\nabla){\mathcal{N}}_{{\bm{w}},{\bm{u}}})_k&=\sum_{m=1}^d\left(\sum_{j=1}^pa_{1m,j}\sigma\left(\sum_{q=1}^dw_{j,q}x_q+w_{j,d+1}t\right)\right) \left(\sum_{j=1}^pa_{1k,j}\sigma'\left(\sum_{q=1}^dw_{j,q}x_q+w_{j,d+1}t\right)w_{j,m}\right)\\
    &=\sum_{m=1}^d(\left\langle{\bm{a}}_{1m},\sigma({\bm{W}}{\bm{z}})\right\rangle)(\left\langle{\bm{a}}_{1k}\odot{\bm{w}}_{{\bm{x}}_m},\sigma'({\bm{W}}{\bm{z}})\right\rangle)\\
\end{align*}
and that the Laplacian is
\begin{align*}
    (\partial_{x_m}^2{\mathcal{N}}_{{\bm{w}},{\bm{u}}}({\bm{z}}))_k&=\sum_{j=1}^pa_{1k,j}\sigma''\left(\sum_{q=1}^dw_{j,q}x_q+w_{j,d+1}t\right)w_{j,m}^2=\left\langle{\bm{a}}_{1k}\odot{\bm{w}}_{x_m}\odot{\bm{w}}_{x_m},\sigma''({\bm{W}}{\bm{z}})\right\rangle\\
    \implies(\nabla^2{\mathcal{N}}_{{\bm{w}},{\bm{u}}}({\bm{z}}))_k&=\sum_{m=1}^d\sum_{j=1}^pa_{1k,j}\sigma''\left(\sum_{q=1}^dw_{j,q}x_q+w_{j,d+1}t\right)w_{j,m}^2=\sum_{m=1}^d\left\langle{\bm{a}}_{1k}\odot{\bm{w}}_{x_m}\odot{\bm{w}}_{x_m},\sigma''({\bm{W}}{\bm{z}})\right\rangle
\end{align*}

\begin{align*}
        \sup_{{\bm{w}}}\abs{\sum_{i=1}^n \epsilon_i f_{\bm{w}}({\bm{z}}_i)} &= \sup_{{\bm{w}}}\abs{\sum_{i=1}^n \epsilon_i (g_{\bm{w}}({\bm{z}}_i) + c)}\leq\sup_{\bm{w}} \left( \abs{\sum_{i=1}^n \epsilon_i g_{\bm{w}}({\bm{z}}_i)} + \abs{\sum_{i=1}^n c\epsilon_i}\right) = \sup_{\bm{w}} \left( \abs{\sum_{i=1}^n \epsilon_i g_{\bm{w}}({\bm{z}}_i)}\right) + \abs{\sum_{i=1}^n c\epsilon_i}
    \end{align*}
    Now, taking the expectation over ${\bm{\epsilon}}$ on both sides we get,
    \begin{align}
        \mathbb{E}_{{\bm{\epsilon}} \sim \{\pm 1\}^n} \left[ \sup_{{\bm{w}}}\abs{\sum_{i=1}^n \epsilon_i f_{\bm{w}}({\bm{z}}_i)} \right] &\leq \mathbb{E}_{{\bm{\epsilon}} \sim \{\pm 1\}^n} \left[ \sup_{\bm{w}} \left( \abs{\sum_{i=1}^n \epsilon_i g_{\bm{w}}({\bm{z}}_i)}\right) \right] + \mathbb{E}_{{\bm{\epsilon}} \sim \{\pm 1\}^n} \left[ \abs{\sum_{i=1}^n c\epsilon_i} \right]\nonumber\\
        &\leq \mathbb{E}_{{\bm{\epsilon}} \sim \{\pm 1\}^n} \left[ \sup_{\bm{w}} \left( \abs{\sum_{i=1}^n \epsilon_i g_{\bm{w}}({\bm{z}}_i)}\right) \right] + \abs{c}\sqrt{n} \label{eq:minitala:1}
    \end{align}
    Let $\phi$ be the ReLU function, then the lemma's assumption implies that $\sup_{{\bm{w}}} \phi\left(\left\langle{\bm{\epsilon}},g_{{\bm{w}}}({\bm{Z}})\right\rangle\right)=\sup_{{\bm{w}}}\left\langle{\bm{\epsilon}},g_{{\bm{w}}}({\bm{Z}})\right\rangle$ for any ${\bm{\epsilon}} \in\{\pm 1\}^{n}$. Observing that $|x|=\phi(x)+\phi(-x)$,
    \begin{align*}
        \sup_{{\bm{w}}}\abs{\left\langle{\bm{\epsilon}},g_{{\bm{w}}}({\bm{Z}})\right\rangle} &=\sup_{{\bm{w}}}\left[\phi\left(\left\langle{\bm{\epsilon}},g_{{\bm{w}}}({\bm{Z}})\right\rangle\right)+\phi\left(\left\langle-{\bm{\epsilon}},g_{{\bm{w}}}({\bm{Z}})\right\rangle\right)\right] \\
        & \leq \sup _{{\bm{w}}} \phi\left(\left\langle{\bm{\epsilon}},g_{{\bm{w}}}({\bm{Z}})\right\rangle\right)+\sup _{{\bm{w}}} \phi\left(\left\langle-{\bm{\epsilon}},g_{{\bm{w}}}({\bm{Z}})\right\rangle\right) \\
        &=\sup_{{\bm{w}}}\left\langle{\bm{\epsilon}},g_{{\bm{w}}}({\bm{Z}})\right\rangle + \sup_{{\bm{w}}}\left\langle-{\bm{\epsilon}},g_{{\bm{w}}}({\bm{Z}})\right\rangle.
    \end{align*}
    Taking the expectation over ${\bm{\epsilon}}$ (and noting that ${\bm{\epsilon}}$ and $-{\bm{\epsilon}}$ have the same distribution) we get,
    \begin{align*}
        \mathbb{E}_{{\bm{\epsilon}} \sim \{\pm 1\}^n} \left[ \sup_{\bm{w}} \abs{\sum_{i=1}^n \epsilon_i g_{\bm{w}}({\bm{z}}_i)} \right] \leq 2\mathbb{E}_{{\bm{\epsilon}} \sim \{\pm 1\}^n} \left[ \sup_{\bm{w}} \left(\sum_{i=1}^n \epsilon_i g_{\bm{w}}({\bm{z}}_i)\right) \right]
    \end{align*}
    Replacing the above into equation~\ref{eq:minitala:1} we get,
    \begin{align}
        \mathbb{E}_{{\bm{\epsilon}} \sim \{\pm 1\}^n} \left[ \sup_{{\bm{w}}}\abs{\sum_{i=1}^n \epsilon_i f_{\bm{w}}({\bm{z}}_i)} \right] &\leq 2\mathbb{E}_{{\bm{\epsilon}} \sim \{\pm 1\}^n} \left[ \sup_{\bm{w}} \left( \sum_{i=1}^n \epsilon_i g_{\bm{w}}({\bm{z}}_i)\right) \right] + \abs{c}\sqrt{n}
    \end{align}

\begin{align*}
        &\mathbb{E}_{{\bm{\epsilon}} \sim \{\pm 1\}^{N_r}} \left[ \sup_{{\bm{W}}\in{\mathcal{C}}} \left( \frac{1}{N_r} \sum_{i=1}^{N_r} \epsilon_i \left\langlef({\bm{W}}),\phi({\bm{W}} {\bm{z}}_i)\right\rangle \right) \right] \nonumber\\
        &= \frac{1}{N_r} \mathbb{E}_{{\bm{\epsilon}} \sim \{\pm 1\}^{N_r}} \left[ \sup_{{\bm{W}}\in{\mathcal{C}}} \left( \sum_{i=1}^{N_r} \epsilon_i \sum_{m=1}^{p} f({\bm{W}})_m \phi(\left\langle{\bm{w}}_m,{\bm{z}}_i\right\rangle) \right) \right] \\
        &= \frac{1}{N_r} \mathbb{E}_{{\bm{\epsilon}} \sim \{\pm 1\}^{N_r}} \left[ \sup_{{\bm{W}}\in{\mathcal{C}}} \left( \sum_{m=1}^{p} f({\bm{W}})_m \sum_{i=1}^{N_r} \epsilon_i \phi(\left\langle{\bm{w}}_m,{\bm{z}}_i\right\rangle) \right) \right] \nonumber\\
        &\leq \frac{1}{N_r} \mathbb{E}_{{\bm{\epsilon}} \sim \{\pm 1\}^{N_r}} \left[ \sup_{{\bm{W}}\in{\mathcal{C}}} \left( \sum_{m=1}^{p} \abs{f({\bm{W}})_m} \max_{k\in[p]} \abs{\sum_{i=1}^{N_r} \epsilon_i \phi(\left\langle{\bm{w}}_k,{\bm{z}}_i\right\rangle)} \right) \right] &&\left( \text{since } \sum_j \alpha_j \beta_j \leq \sum_j \abs{\alpha_j} \max_k \abs{\beta_k} \right)\\
        &\leq \frac{B}{N_r} \mathbb{E}_{{\bm{\epsilon}} \sim \{\pm 1\}^{N_r}} \left[ \sup_{{\bm{W}}\in{\mathcal{C}}} \max_{k\in[p]} \abs{\sum_{i=1}^{N_r} \epsilon_i \phi(\left\langle{\bm{w}}_k,{\bm{z}}_i\right\rangle)} \right] &&\left( \text{since } \sum_{m=1}^{p} \abs{f({\bm{W}})_m} \leq B \right)\\
        &= \frac{B}{N_r} \mathbb{E}_{{\bm{\epsilon}} \sim \{\pm 1\}^{N_r}} \left[ \sup_{\bar{{\bm{w}}}\in\textrm{RS}({\mathcal{C}})} \abs{\sum_{i=1}^{N_r} \epsilon_i \phi(\left\langle\bar{{\bm{w}}},{\bm{z}}_i\right\rangle)} \right]
    \end{align*}
    We then apply Lemma \ref{lem:dabsvalremtanh} with $f_{\bar{{\bm{w}}}}({\bm{z}}_i) = \phi(\langle \bar{{\bm{w}}}, {\bm{z}}_i\rangle)$ and constant $c = \phi_1(0)$, so that $g_{\bar{{\bm{w}}}}({\bm{z}}_i) = \phi(\langle \bar{{\bm{w}}}, {\bm{z}}_i\rangle)-c$ vanishes at $\bar{{\bm{w}}} = 0$. The condition $\sup_{\bar{{\bm{w}}}} \langle \epsilon, g_{\bar{{\bm{w}}}}({\bm{Z}})\rangle \geq 0$ holds since the supremum is taken over the zero vector as a feasible point. Lemma \ref{lem:dabsvalremtanh} then gives:


    \begin{align*}
        &\leq \frac{B}{N_r} \left\{2\mathbb{E}_{{\bm{\epsilon}} \sim \{\pm 1\}^{N_r}} \left[ \sup_{\bar{{\bm{w}}}\in\textrm{RS}({\mathcal{C}})} \sum_{i=1}^{N_r} \epsilon_i g(\left\langle\bar{{\bm{w}}},{\bm{z}}_i\right\rangle) \right] + \abs{c}\sqrt{N_r}\right\}
    \end{align*}    
    Now, $\chi(\cdot)$ has the same Lipschitz constant as $\phi(\cdot)$,  we can apply Talagrand's contraction lemma to get,
    \begin{align}
        &\leq \frac{2B L_{\phi}}{N_r} \mathbb{E}_{{\bm{\epsilon}} \sim \{\pm 1\}^{N_r}} \left[ \sup_{\bar{{\bm{w}}}\in\textrm{RS}({\mathcal{C}})} \sum_{i=1}^{N_r} \epsilon_i \left\langle\bar{{\bm{w}}},{\bm{z}}_i\right\rangle \right] + \frac{B\abs{c}}{\sqrt{N_r}}
    \end{align}

\begin{align*}
        &\mathbb{E}_{\substack{{\bm{\epsilon}} \sim \{\pm 1\}^{N_r}}} \left[ \sup_{{\bm{W}}\in{\mathcal{C}}} \left(\frac{1}{N_r} \sum_{i=1}^{N_r}\sum_{m=1}^d \epsilon_i \left\langlef_m({\bm{W}}),\phi_1 ({\bm{W}} {\bm{z}}_i)\right\rangle \left\langle{\bm{a}}_m,\phi_2({\bm{W}} {\bm{z}}_i)\right\rangle \right)\right] \nonumber\\
        &=\frac{1}{N_r} \mathbb{E}_{\substack{{\bm{\epsilon}} \sim \{\pm 1\}^{N_r}}} \left[ \sup_{{\bm{W}}\in{\mathcal{C}}} \left( \sum_{i=1}^{N_r}\sum_{m=1}^d \epsilon_i \sum_{q_1,q_2 = 1}^p f_m({\bm{W}})_{q_1} \phi_1(\left\langle{\bm{w}}_{q_1},{\bm{z}}_i\right\rangle) {\bm{a}}_{m,q_2}\phi_2(\left\langle{\bm{w}}_{q_2},{\bm{z}}_i\right\rangle) \right)\right] \nonumber\\
        &=\frac{1}{N_r}\mathbb{E}_{\substack{{\bm{\epsilon}} \sim \{\pm 1\}^{N_r}}} \left[ \sup_{{\bm{W}}\in{\mathcal{C}}} \left( \sum_{m=1}^d\sum_{q_1,q_2 = 1}^p f_m({\bm{W}})_{q_1} {\bm{a}}_{m,q_2} \sum_{i=1}^{N_r} \epsilon_i  \phi_1(\left\langle{\bm{w}}_{q_1},{\bm{z}}_i\right\rangle)\phi_2(\left\langle{\bm{w}}_{q_2},{\bm{z}}_i\right\rangle) \right)\right]
        \end{align*}
     Using $\sum_j \alpha_j \beta_j \leq \sum_j \abs{\alpha_j} \max_k \abs{\beta_k}$,
        \begin{align*}
        &\leq\frac{1}{N_r}\mathbb{E}_{\substack{{\bm{\epsilon}} \sim \{\pm 1\}^{N_r}}} \left[ \sup_{{\bm{W}}\in{\mathcal{C}}} \left( \sum_{m=1}^d\sum_{q_1,q_2 = 1}^p \abs{f_m({\bm{W}})_{q_1}} \abs{{\bm{a}}_{m,q_2}} \max_{q_1,q_2 \in [p]} \abs{\sum_{i=1}^{N_r} \epsilon_i  \phi_1(\left\langle{\bm{w}}_{q_1},{\bm{z}}_i\right\rangle)\phi_2(\left\langle{\bm{w}}_{q_2},{\bm{z}}_i\right\rangle)} \right)\right]
    \end{align*}
    Since $\sum_{m=1}^d\sum_{q_1,q_2 = 1}^p \abs{f_m({\bm{W}})_{q_1}} \abs{{\bm{a}}_{m,q_2}} \leq B$,



    \begin{align*}
        &\leq\frac{B}{N_r}\mathbb{E}_{\substack{{\bm{\epsilon}} \sim \{\pm 1\}^{N_r}}} \left[ \sup_{{\bm{W}}\in{\mathcal{C}}} \max_{q_1,q_2 \in [p]} \abs{\sum_{i=1}^{N_r} \epsilon_i  \phi_1(\left\langle{\bm{w}}_{q_1},{\bm{z}}_i\right\rangle)\phi_2(\left\langle{\bm{w}}_{q_2},{\bm{z}}_i\right\rangle)} \right]\\
        &= \frac{B}{N_r}\mathbb{E}_{\substack{{\bm{\epsilon}} \sim \{\pm 1\}^{N_r}}} \left[ \sup_{\bar{{\bm{w}}_1},\bar{{\bm{w}}_2}\in\textrm{RS}({\mathcal{C}})} \abs{\sum_{i=1}^{N_r} \epsilon_i  \phi_1(\left\langle\bar{{\bm{w}}}_1,{\bm{z}}_i\right\rangle)\phi_2(\left\langle\bar{{\bm{w}}}_2,{\bm{z}}_i\right\rangle)} \right]
    \end{align*}
    We then apply Lemma \ref{lem:dabsvalremtanh} with $f_{\bm{w}}({\bm{z}}_i) = \phi_1(\langle {\bm{w}}_1, {\bm{z}}_i\rangle)\phi_2(\langle {\bm{w}}_2, {\bm{z}}_i\rangle)$ and constant $c = \phi_1(0)\cdot\phi_2(0) = k$, so that $g_{\bm{w}}(z_i) = \phi_1(\langle {\bm{w}}_1, {\bm{z}}_i\rangle)\phi_2(\langle {\bm{w}}_2, {\bm{z}}_i\rangle) - k$ vanishes at ${\bm{w}} = 0$. The condition $\sup_{\bm{w}} \langle \epsilon, g_{\bm{w}}({\bm{Z}})\rangle \geq 0$ holds since the supremum is taken over the zero vector as a feasible point. Lemma \ref{lem:dabsvalremtanh} then gives:


    \begin{align}
        &\nonumber\leq\frac{B}{N_r} \left\{2\mathbb{E}_{\substack{{\bm{\epsilon}} \sim \{\pm 1\}^{N_r}}} \left[ \sup_{\bar{{\bm{w}}}_1\bar{{\bm{w}}}_2\in\textrm{RS}({\mathcal{C}})} \sum_{i=1}^{N_r} \epsilon_i  (\phi_1(\left\langle\bar{{\bm{w}}}_{1},{\bm{z}}_i\right\rangle)\phi_2(\left\langle\bar{{\bm{w}}}_2,{\bm{z}}_i\right\rangle) - k)\right] + \abs{k}\sqrt{N_r}\right\}\\
        &\nonumber=\frac{B}{N_r} \left\{2\mathbb{E}_{\substack{{\bm{\epsilon}} \sim \{\pm 1\}^{N_r}}} \left[ \sup_{\bar{{\bm{w}}}_1\bar{{\bm{w}}}_2\in\textrm{RS}({\mathcal{C}})} \sum_{i=1}^{N_r} \epsilon_i  \phi_1(\left\langle\bar{{\bm{w}}}_{1},{\bm{z}}_i\right\rangle)\phi_2(\left\langle\bar{{\bm{w}}}_2,{\bm{z}}_i\right\rangle)\right] -2\mathbb{E}_{\substack{{\bm{\epsilon}} \sim \{\pm 1\}^{N_r}}} \left[\sum_{i=1}^{N_r} \epsilon_i k\right]+ \abs{k}\sqrt{N_r}\right\}\\
        &=\frac{B}{N_r} \left\{2\mathbb{E}_{\substack{{\bm{\epsilon}} \sim \{\pm 1\}^{N_r}}} \left[ \sup_{\bar{{\bm{w}}}_1\bar{{\bm{w}}}_2\in\textrm{RS}({\mathcal{C}})} \sum_{i=1}^{N_r} \epsilon_i  \phi_1(\left\langle\bar{{\bm{w}}}_{1},{\bm{z}}_i\right\rangle)\phi_2(\left\langle\bar{{\bm{w}}}_2,{\bm{z}}_i\right\rangle)\right] + \abs{k}\sqrt{N_r}\right\} \label{eq:after_lemma5}
    \end{align}
where the last step comes from the fact that $\mathbb{E}_{\substack{{\bm{\epsilon}} \sim \{\pm 1\}^{N_r}}} \left[\sum_{i=1}^{N_r} \epsilon_i \right]=\sum_{i=1}^{N_r}\mathbb{E}_{\substack{{\bm{\epsilon}} \sim \{\pm 1\}^{N_r}}} \left[ \epsilon_i \right]=0$.

It remains to bound the Rademacher complexity of the function class
$\mathcal{G} = \{\psi_{{\bm{w}}_1,{\bm{w}}_2} : {\bm{w}}_1, {\bm{w}}_2 \in \mathrm{RS}(C)\}$,
where $\psi_{{\bm{w}}_1,{\bm{w}}_2}(z) := \phi_1(\langle {\bm{w}}_1, z\rangle)\phi_2(\langle {\bm{w}}_2, z\rangle)$.
We proceed in two sequential contraction steps, freezing one supremum 
variable at a time.

\medskip
\noindent\textbf{$\bullet$ (Splitting across a reference weight ${{\bm{w}}}_2^*$)}
Fix any reference vector ${\bm{w}}_2^* \in \mathrm{RS}(C)$. For any fixed $\bar{{\bm{w}}}_1$, 
the scalars $\phi_1(\langle \bar{{\bm{w}}}_1, {\bm{z}}_i\rangle)$ are deterministic, 
and since $|\phi_1(\cdot)| \leq B_{\phi_1}$, we have:

\begin{align}
    &\mathbb{E}_{\epsilon}\left[\sup_{\bar{{\bm{w}}}_1, \bar{{\bm{w}}}_2 \in \mathrm{RS}(C)} \sum_{i=1}^{N_r} \epsilon_i\, \phi_1(\langle \bar{{\bm{w}}}_1, {\bm{z}}_i\rangle)\phi_2(\langle \bar{{\bm{w}}}_2, {\bm{z}}_i\rangle)\right] \notag\\
    &\leq \mathbb{E}_{\epsilon}\left[\sup_{\bar{{\bm{w}}}_1 \in \mathrm{RS}(C)}\left\{ \sup_{\bar{{\bm{w}}}_2 \in \mathrm{RS}(C)} \sum_{i=1}^{N_r} \epsilon_i\, \phi_1(\langle \bar{{\bm{w}}}_1, {\bm{z}}_i\rangle) \left[\phi_2(\langle \bar{{\bm{w}}}_2, {\bm{z}}_i\rangle) - \phi_2(\langle {\bm{w}}_2^*, {\bm{z}}_i\rangle)\right]  + \sum_{i=1}^{N_r} \epsilon_i\, \phi_1(\langle \bar{{\bm{w}}}_1, {\bm{z}}_i\rangle)\phi_2(\langle {\bm{w}}_2^*, {\bm{z}}_i\rangle)\right\}\right] \notag\\
    &\leq \mathbb{E}_{\epsilon}\left[\sup_{\bar{{\bm{w}}}_1, \bar{{\bm{w}}}_2 \in \mathrm{RS}(C)} \sum_{i=1}^{N_r} \epsilon_i\, \phi_1(\langle \bar{{\bm{w}}}_1, {\bm{z}}_i\rangle) \left[\phi_2(\langle \bar{{\bm{w}}}_2, {\bm{z}}_i\rangle) - \phi_2(\langle {\bm{w}}_2^*, {\bm{z}}_i\rangle)\right]\right] 
     + \mathbb{E}_{\epsilon}\left[\sup_{\bar{{\bm{w}}}_1 \in \mathrm{RS}(C)} \sum_{i=1}^{N_r} \epsilon_i\, \phi_1(\langle \bar{{\bm{w}}}_1, {\bm{z}}_i\rangle)\phi_2(\langle {\bm{w}}_2^*, {\bm{z}}_i\rangle)\right]. \label{eq:split}
\end{align}

For the first term in \eqref{eq:split}, since $|\phi_1(\langle \bar{{\bm{w}}}_1, {\bm{z}}_i\rangle)| \leq B_{\phi_1}$ we get,

\begin{align*}
    &\mathbb{E}_{\epsilon}\left[\sup_{\bar{{\bm{w}}}_1, \bar{{\bm{w}}}_2 \in \mathrm{RS}(C)} \sum_{i=1}^{N_r} \epsilon_i\, \phi_1(\langle \bar{{\bm{w}}}_1, {\bm{z}}_i\rangle) \left[\phi_2(\langle \bar{{\bm{w}}}_2, {\bm{z}}_i\rangle) - \phi_2(\langle {\bm{w}}_2^*, {\bm{z}}_i\rangle)\right]\right]\\ 
    &\leq \mathbb{E}_{\epsilon}\left[\sup_{\bar{{\bm{w}}}_2 \in \mathrm{RS}(C)} \left|\sum_{i=1}^{N_r} \epsilon_i \phi_1(\bar{{\bm{w}}}_1, {\bm{z}}_i) \left[\phi_2(\langle \bar{{\bm{w}}}_2, {\bm{z}}_i\rangle) - \phi_2(\langle {\bm{w}}_2^*, {\bm{z}}_i\rangle)\right]\right|\right]\\
    &\leq B_{\phi_1}\, \mathbb{E}_{\epsilon}\left[\sup_{\bar{{\bm{w}}}_2 \in \mathrm{RS}(C)} \left|\sum_{i=1}^{N_r} \epsilon_i \left[\phi_2(\langle \bar{{\bm{w}}}_2, {\bm{z}}_i\rangle) - \phi_2(\langle {\bm{w}}_2^*, {\bm{z}}_i\rangle)\right]\right|\right]
\end{align*}
We apply Lemma~\ref{lem:dabsvalremtanh} with $f_{\bm{w}}({\bm{z}}_i) = \phi_2(\langle \bar{{\bm{w}}}_2, {\bm{z}}_i\rangle) - \phi_2(\langle {\bm{w}}_2^*, {\bm{z}}_i\rangle)$ and constant $c = 0$,
so that $g_w({\bm{z}}_i) = \phi_2(\langle \bar{{\bm{w}}}_2, {\bm{z}}_i\rangle) - \phi_2(\langle {\bm{w}}_2^*, {\bm{z}}_i\rangle)$ vanishes at $\bar{{\bm{w}}}_2 = {\bm{w}}_2^*$.
The condition $\sup_{\bm{w}} \langle \epsilon, g_w({\bm{Z}})\rangle \geq 0$ holds since 
the supremum is taken over the zero vector as a feasible point. Therefore, for the first term in the RHS of \eqref{eq:split} we get,
\begin{align*}
    \mathbb{E}_{\epsilon}\left[\sup_{\bar{{\bm{w}}}_1, \bar{{\bm{w}}}_2 \in \mathrm{RS}(C)} \sum_{i=1}^{N_r} \epsilon_i\, \phi_1(\langle \bar{{\bm{w}}}_1, {\bm{z}}_i\rangle) \left[\phi_2(\langle \bar{{\bm{w}}}_2, {\bm{z}}_i\rangle) - \phi_2(\langle {\bm{w}}_2^*, {\bm{z}}_i\rangle)\right]\right] &\leq 2 B_{\phi_1}\, \mathbb{E}_{\epsilon}\left[\sup_{\bar{{\bm{w}}}_2 \in \mathrm{RS}(C)} \sum_{i=1}^{N_r} \epsilon_i \left[\phi_2(\langle \bar{{\bm{w}}}_2, {\bm{z}}_i\rangle) - \phi_2(\langle {\bm{w}}_2^*, {\bm{z}}_i\rangle)\right]\right]\\
    &\leq 2B_{\phi_1} L_{\phi_2}\, \mathbb{E}_{\epsilon}\left[\sup_{\bar{{\bm{w}}} \in \mathrm{RS}(C)} \sum_{i=1}^{N_r} \epsilon_i \langle \bar{{\bm{w}}}, {\bm{z}}_i\rangle\right],
\end{align*}

where the last step uses Talagrand's contraction on 
$\phi_2(\langle \bar{{\bm{w}}}_2, {\bm{z}}_i\rangle) - \phi_2(\langle {\bm{w}}_2^*, {\bm{z}}_i\rangle)$,
which is $L_{\phi_2}$-Lipschitz in $\langle \bar{{\bm{w}}}_2, {\bm{z}}_i\rangle$.


\medskip
\noindent \textbf{$\bullet$ (Contract over $\bar{{\bm{w}}}_1$ with ${\bm{w}}_2^*$ fixed)}
We now handle the second term in \eqref{eq:split}. 
Since ${\bm{w}}_2^*$ is a fixed reference vector, $\phi_2(\langle {\bm{w}}_2^*, {\bm{z}}_i\rangle)$ 
is a fixed scalar for each $i$. Using $|\phi_2(\langle {\bm{w}}_2^*, {\bm{z}}_i\rangle)| \leq B_{\phi_2}$:

\begin{align*}
    &\mathbb{E}_{\epsilon}\left[\sup_{\bar{{\bm{w}}}_1 \in \mathrm{RS}(C)} \sum_{i=1}^{N_r} \epsilon_i\, \phi_1(\langle \bar{{\bm{w}}}_1, {\bm{z}}_i\rangle)\phi_2(\langle {\bm{w}}_2^*, {\bm{z}}_i\rangle)\right]\leq \mathbb{E}_{\epsilon}\left[\sup_{\bar{{\bm{w}}}_1 \in \mathrm{RS}(C)} \abs{\sum_{i=1}^{N_r} \epsilon_i\, \phi_1(\langle \bar{{\bm{w}}}_1, {\bm{z}}_i\rangle)\phi_2(\langle {\bm{w}}_2^*, {\bm{z}}_i\rangle)}\right]\\
    &\leq B_{\phi_2}\, \mathbb{E}_{\epsilon}\left[\sup_{\bar{{\bm{w}}}_1 \in \mathrm{RS}(C)} \left|\sum_{i=1}^{N_r} \epsilon_i\, \phi_1(\langle \bar{{\bm{w}}}_1, {\bm{z}}_i\rangle)\right|\right].
\end{align*}

We apply Lemma~\ref{lem:dabsvalremtanh} 
with $f_{\bm{w}}({\bm{z}}_i) = \phi_1(\langle {\bm{w}}, {\bm{z}}_i\rangle)$ and constant $c = \phi_1(0) = c_0$,
so that $g_{\bm{w}}({\bm{z}}_i) = \phi_1(\langle {\bm{w}}, {\bm{z}}_i\rangle) - c_0$ vanishes at ${\bm{w}} = 0$.
The condition $\sup_w \langle \epsilon, g_{\bm{w}}(Z)\rangle \geq 0$ holds since 
the supremum is taken over the zero vector as a feasible point. Hence for the second term in the RHS of \eqref{eq:split} we get,


\begin{align*}
    \mathbb{E}_{\epsilon}\left[\sup_{\bar{{\bm{w}}}_1 \in \mathrm{RS}(C)} \sum_{i=1}^{N_r} \epsilon_i\, \phi_1(\langle \bar{{\bm{w}}}_1, {\bm{z}}_i\rangle)\phi_2(\langle {\bm{w}}_2^*, {\bm{z}}_i\rangle)\right] \leq 2 B_{\phi_2}\,\mathbb{E}_{\epsilon}\left[\sup_{\bar{{\bm{w}}}_1 \in \mathrm{RS}(C)} \sum_{i=1}^{N_r} \epsilon_i \left[\phi_1(\langle \bar{{\bm{w}}}_1, {\bm{z}}_i\rangle) - c_0\right]\right] + B_{\phi_2}|c_0|\sqrt{N_r}.
\end{align*}

Now $\phi_1(\langle \bar{{\bm{w}}}_1, {\bm{z}}_i\rangle) - c_0$ is an 
$L_{\phi_1}$-Lipschitz function of $\langle \bar{{\bm{w}}}_1, {\bm{z}}_i\rangle$, so Talagrand's contraction applies to give,

\begin{align*}
    \mathbb{E}_{\epsilon}\left[\sup_{\bar{{\bm{w}}}_1 \in \mathrm{RS}(C)} \sum_{i=1}^{N_r} \epsilon_i\, \phi_1(\langle \bar{{\bm{w}}}_1, {\bm{z}}_i\rangle)\phi_2(\langle {\bm{w}}_2^*, {\bm{z}}_i\rangle)\right] \leq 2 B_{\phi_2} L_{\phi_1}\,\mathbb{E}_{\epsilon}\left[\sup_{\bar{{\bm{w}}} \in \mathrm{RS}(C)} \sum_{i=1}^{N_r} \epsilon_i \langle \bar{{\bm{w}}}, {\bm{z}}_i\rangle\right] + B_{\phi_2}|c_0|\sqrt{N_r}.
\end{align*}

\medskip
\noindent\textbf{$\bullet$ (Combining)} Substituting into \eqref{eq:split} the end results of the above two analysis blocks we get,

\begin{align*}
    \mathbb{E}_{\epsilon}\left[\sup_{\bar{{\bm{w}}}_1, \bar{{\bm{w}}}_2 \in \mathrm{RS}(C)} \sum_{i=1}^{N_r} \epsilon_i\, \phi_1(\langle \bar{{\bm{w}}}_1, {\bm{z}}_i\rangle)\phi_2(\langle \bar{{\bm{w}}}_2, {\bm{z}}_i\rangle)\right]
    \leq 2(B_{\phi_1} L_{\phi_2} + B_{\phi_2} L_{\phi_1})\, \mathbb{E}_{\epsilon}\left[\sup_{\bar{{\bm{w}}} \in \mathrm{RS}(C)} \sum_{i=1}^{N_r} \epsilon_i \langle \bar{{\bm{w}}}, {\bm{z}}_i\rangle\right] + B_{\phi_2}|c_0|\sqrt{N_r}.
\end{align*}

Substituting the above back into \eqref{eq:after_lemma5} we get the desired bound,
\begin{align}
    &\mathbb{E}_{\epsilon \sim \{\pm 1\}^{N_r}}\left[\sup_{W \in C} \left(\frac{1}{N_r}\sum_{i=1}^{N_r} \sum_{m=1}^{d} \epsilon_i \langle f_m(W), \phi_1(W{\bm{z}}_i)\rangle \langle a_m, \phi_2(W{\bm{z}}_i)\rangle \right)\right] \notag \\
    &\leq \frac{B}{N_r}\left\{4(B_{\phi_1} L_{\phi_2} + B_{\phi_2} L_{\phi_1})\, \mathbb{E}_{\epsilon}\left[\sup_{\bar{{\bm{w}}} \in \mathrm{RS}(C)} \sum_{i=1}^{N_r} \epsilon_i \langle \bar{{\bm{w}}}, {\bm{z}}_i\rangle\right] + 2 B_{\phi_2}|c_0|\sqrt{N_r} + |k|\sqrt{N_r}\right\}\\
    &=\frac{4B(B_{\phi_1} L_{\phi_2} + B_{\phi_2} L_{\phi_1})}{N_r}\, \mathbb{E}_{\epsilon}\left[\sup_{\bar{{\bm{w}}} \in \mathrm{RS}(C)} \sum_{i=1}^{N_r} \epsilon_i \langle \bar{{\bm{w}}}, {\bm{z}}_i\rangle\right] + \frac{B(2B_{\phi_2}|c_0| + |k|)}{\sqrt{N_r}}. \nonumber
\end{align}
